540:  ****************************************************************************/541: 542: void rk3576_vop_full_dump(void);543: 544: /* The VOP's own error/event reporting, as latched by the hardware.545:  *546:  * This driver registers no IRQ handler, so these bits are the only way to547:  * learn that the display pipeline itself is unhappy.  That matters because548:  * the failure this board is chasing (a dark panel with a clean DSI link) has549:  * two candidates that look identical from the DSI side:550:  *551:  *   bus_errpr      - a window's AXI read failed, so the compositor had no552:  *                    pixel data.  The DSI still transmits, the panel sees553:  *                    well-formed packets and reports no errors, and the554:  *                    screen is black.555:  *   post_buf_empty - the POST's output buffer underran, i.e. the hardware's556:  *                    own statement that pixels did not arrive in time.557:  *558:  * Reading either of those as set changes the investigation completely, so559:  * they are sampled during the live observation rather than assumed absent.560:  */561: 562: struct rk3576_vop_int_s563: {564:   uint32_t sys0;      /* SYS0_INT_STATUS (AXI bus 0). */565:   uint32_t sys1;      /* SYS1_INT_STATUS (AXI bus 1). */566:   uint32_t vp_raw;    /* VP_INT_RAW_STATUS of the configured port. */567:   uint32_t vp_status; /* VP_INT_STATUS of the configured port (masked). */568: 569:   /* The same bits, already decoded, so callers do not need the register570:    * layout to interpret them. */571: 572:   bool bus_error;      /* A window's AXI read failed. */573:   bool post_buf_empty; /* The POST output buffer underran. */574:   bool frame_start;    /* The timing generator produced frame starts. */575:   bool line_flag;      /* A line-flag position was reached. */576: };577: 578: /****************************************************************************579:  * Name: rk3576_vop_get_int_status580:  *581:  * Description:582:  *   Read the VOP's latched interrupt state for the configured port.583:  *584:  *   RAW_STATUS is reported alongside STATUS on purpose: the raw register is585:  *   not filtered by the interrupt-enable mask, and since this driver enables586:  *   no VOP interrupts the masked register would read 0 whether or not587:  *   anything happened.588:  *589:  * Input Parameters:590:  *   status - Destination snapshot (must not be NULL).591:  *   clear  - Also clear the latched bits, so the next call reports only what592:  *            happened since this one (attribution per observation window).593:  *594:  * Returned Value:595:  *   OK, or -ENODEV if the VOP has not been initialised.596:  *597:  ****************************************************************************/598: 599: int rk3576_vop_get_int_status(FAR struct rk3576_vop_int_s *status,600:                               bool clear);601: 602: #endif /* CONFIG_RK3576_VOP */603: #endif /* __VENDOR_ROCKCHIP_RK3576_RK3576_VOP_H */=== 残留探针名(应为空) ===
